CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor cumprod_lastdim_cuda(torch::Tensor input);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("cumprod_lastdim", &cumprod_lastdim_cuda,
          "Cumulative product along the last (contiguous) dimension (CUDA fp32)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// One block per row; threads iterate sequentially through the row so the
// running product stays in registers.  Block size is chosen to keep
// occupancy reasonable while the per-block work stays large.
//
// Grid:  (num_rows,)
// Block: (BLOCK_SIZE,)  -- only thread 0 does the actual scan; other
//         threads are not launched (we use 1 thread per block so the
//         compiler keeps register pressure minimal and we avoid any
//         synchronization overhead for the purely-serial scan).
//
// For a 32768x32768 fp32 matrix scanned along dim=1 this gives 32768
// independent serial scans, each 32768 elements long, which the GPU
// can pipeline across SMs with full DRAM coalescing on the write side.

__launch_bounds__(256, 4)
__global__ void cumprod_lastdim_kernel(
        const float* __restrict__ input,
        float*       __restrict__ output,
        int row_len) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    // Each thread handles one complete row.
    const float* in_row  = input  + (long long)row * row_len;
    float*       out_row = output + (long long)row * row_len;

    float acc = 1.0f;
    // Scalar serial scan -- accumulator lives in a register the whole time.
    for (int i = 0; i < row_len; ++i) {
        acc *= __ldg(in_row + i);
        out_row[i] = acc;
    }
}

torch::Tensor cumprod_lastdim_cuda(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "only float32 supported");
    TORCH_CHECK(input.dim() >= 1, "input must have at least one dimension");

    auto output = torch::empty_like(input);

    int row_len  = (int)input.size(input.dim() - 1);
    long long num_rows = input.numel() / row_len;

    // 256 threads per block, each thread owns one row.
    const int BLOCK = 256;
    int grid = (int)((num_rows + BLOCK - 1) / BLOCK);

    cumprod_lastdim_kernel<<<grid, BLOCK>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        row_len);

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        A model that performs a cumulative product operation along a specified dimension.

        Parameters:
            dim (int): The dimension along which to perform the cumulative product operation.
        """
    def __init__(self, dim):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                Initialize the CumulativeProductModel.

                Args:
                    dim (int): The dimension along which to perform the cumulative product.
                """
        self.dim = dim
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        ndim = x.dim()
        dim_norm = self.dim if self.dim >= 0 else self.dim + ndim
        last_dim = ndim - 1
        use_fast = (
        x.is_cuda
        and x.is_contiguous()
        and x.dtype == torch.float32
        and dim_norm == last_dim
        )
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if use_fast:
            return _stark_get_extension().cumprod_lastdim(x)
        return torch.cumprod(x, dim=self.dim)
        # <<<END_IMPROVE>>>

