#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Each block handles one row. Threads in the block collectively process
// the row in float4 chunks, then fix up with a warp-scan carry pass.
// Block size: 256 threads; each thread covers 4 elements -> 1024 elements per pass.
// For rows > 1024, we loop with a stride of BLOCK_SIZE*4.

#define BLOCK_SIZE 256

__global__ void cumprod_vec4_kernel(const float* __restrict__ in,
                                     float* __restrict__ out,
                                     int ncols) {
    const int row = blockIdx.x;
    const int tid = threadIdx.x;
    const int lane = tid & 31;
    const int wid  = tid >> 5;   // warp index within block
    const int nwarps = BLOCK_SIZE / 32;

    // shared: per-warp last products, and inter-warp prefix carry
    __shared__ float warp_last[8];   // nwarps <= 8
    __shared__ float warp_prefix[8];

    const float* row_in  = in  + (long long)row * ncols;
    float*       row_out = out + (long long)row * ncols;

    // running carry into the current chunk (across iterations of the outer loop)
    float block_carry = 1.0f;

    int chunks = (ncols / 4);          // number of float4 chunks
    int tail   = ncols - chunks * 4;   // leftover scalar elements

    // --- vectorized pass over full float4 chunks ---
    // outer loop: stride over chunks in steps of BLOCK_SIZE
    for (int base = 0; base < chunks; base += BLOCK_SIZE) {
        int chunk_idx = base + tid;   // which float4 this thread handles
        float v0, v1, v2, v3;
        if (chunk_idx < chunks) {
            const float4 vec = reinterpret_cast<const float4*>(row_in)[chunk_idx];
            v0 = vec.x; v1 = vec.y; v2 = vec.z; v3 = vec.w;
            // intra-thread prefix
            v1 *= v0; v2 *= v1; v3 *= v2;
        } else {
            v0 = v1 = v2 = v3 = 1.0f;
        }
        // last element of this thread's vec4 local prefix
        float local_last = v3;

        // --- warp-level prefix scan on local_last using shuffle ---
        // exclusive scan so each thread gets the product of all previous lanes
        float val = local_last;
        #pragma unroll
        for (int offset = 1; offset < 32; offset <<= 1) {
            float n = __shfl_up_sync(0xffffffff, val, offset);
            if (lane >= offset) val *= n;
        }
        // val is now inclusive scan; exclusive = val / local_last * 1
        float excl = __shfl_up_sync(0xffffffff, val, 1);
        if (lane == 0) excl = 1.0f;
        // store warp's total (last lane's inclusive) for inter-warp scan
        if (lane == 31) warp_last[wid] = val;
        __syncthreads();

        // inter-warp exclusive prefix in warp 0
        if (wid == 0) {
            float w = (lane < nwarps) ? warp_last[lane] : 1.0f;
            float ws = w;
            #pragma unroll
            for (int offset = 1; offset < 32; offset <<= 1) {
                float n2 = __shfl_up_sync(0xffffffff, ws, offset);
                if (lane >= offset) ws *= n2;
            }
            float we = __shfl_up_sync(0xffffffff, ws, 1);
            if (lane == 0) we = 1.0f;
            if (lane < nwarps) warp_prefix[lane] = we;
        }
        __syncthreads();

        // combine: carry from previous block-level pass + inter-warp prefix + intra-warp exclusive
        float carry_in = block_carry * warp_prefix[wid] * excl;

        if (chunk_idx < chunks) {
            float4 res;
            res.x = carry_in * v0;
            res.y = carry_in * v1;
            res.z = carry_in * v2;
            res.w = carry_in * v3;
            reinterpret_cast<float4*>(row_out)[chunk_idx] = res;
        }

        // update block_carry: product of all elements processed so far
        // = block_carry * (total product of this BLOCK_SIZE*4 chunk)
        // total = warp_prefix[nwarps-1] * warp_last[nwarps-1] if last warp is full
        // easier: last thread in the block computes its inclusive result
        if (tid == min(BLOCK_SIZE, chunks - base) - 1) {
            // this thread wrote the last chunk in this iteration
            block_carry = block_carry * warp_prefix[wid] * val;
        }
        // broadcast block_carry from the last active thread
        int last_active = min(BLOCK_SIZE, chunks - base) - 1;
        block_carry = __shfl_sync(0xffffffff,
            block_carry,
            last_active & 31,   // lane within its warp
            32);
        // now broadcast from the warp that held last_active
        {
            int src_warp = last_active >> 5;
            // all warps need the same value; warp 0 picks it from shared if needed
            __shared__ float bc_shared;
            if (tid == last_active) bc_shared = block_carry;
            __syncthreads();
            block_carry = bc_shared;
