#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Each block handles one row. Each thread processes 2 consecutive float4 chunks
// (8 elements) per outer-loop iteration, halving sync rounds for long rows.
// Block size: 256 threads -> 2048 elements per outer-loop step.

#define BLOCK_SIZE 256

__global__ void cumprod_vec8_kernel(const float* __restrict__ in,
                                     float* __restrict__ out,
                                     int ncols) {
    const int row = blockIdx.x;
    const int tid = threadIdx.x;
    const int lane = tid & 31;
