    for (int base = 0; base < chunks; base += stride) {
        // Chunk indices for this thread's two float4 loads
        int ci0 = base + tid;
        int ci1 = base + BLOCK_SIZE + tid;

        // Load first float4
        float a0, a1, a2, a3;
        bool valid0 = (ci0 < chunks);
        if (valid0) {
            float4 v = reinterpret_cast<const float4*>(row_in)[ci0];
            a0 = v.x; a1 = v.y; a2 = v.z; a3 = v.w;
            a1 *= a0; a2 *= a1; a3 *= a2;
